/**
 * The names of an order's statuses: the one list of the app (the orders card,
 * the order's details, the driver map and the messages read it), so a status
 * has one name on every screen.
 *
 * Each name's translation call is written out with its key and its English
 * text, never built from a table: the translation catalog is generated by
 * scanning these calls.
 */
type Translate = (key: string, fallback?: string) => string

export interface OrderStatusEntry {
  /** The status number of the API. */
  key: number
  /** The translated name. */
  value: string
  /** The same name, under the field the orders list reads. */
  text: string
  /** The translation key of the name. */
  slug: string
  /** How far the order is, from 0 to 1. */
  percentage: number
}

const entry = (key: number, slug: string, name: string, percentage: number): OrderStatusEntry =>
  ({ key, value: name, text: name, slug, percentage })

/** Every status with its translated name, in the order of the status numbers. */
export const orderStatusList = (t: Translate): OrderStatusEntry[] => [
  entry(0, 'PENDING', t('PENDING', 'Pending'), 0.25),
  entry(1, 'COMPLETED', t('COMPLETED', 'Completed'), 1),
  entry(2, 'REJECTED', t('REJECTED', 'Rejected'), 0),
  entry(3, 'DRIVER_IN_BUSINESS', t('DRIVER_IN_BUSINESS', 'Driver in business'), 0.6),
  entry(4, 'READY_FOR_PICKUP', t('READY_FOR_PICKUP', 'Ready for pickup'), 0.7),
  entry(5, 'REJECTED_BY_BUSINESS', t('REJECTED_BY_BUSINESS', 'Rejected by business'), 0),
  entry(6, 'REJECTED_BY_DRIVER', t('REJECTED_BY_DRIVER', 'Rejected by Driver'), 0),
  entry(7, 'ACCEPTED_BY_BUSINESS', t('ACCEPTED_BY_BUSINESS', 'Accepted by business'), 0.35),
  entry(8, 'ACCEPTED_BY_DRIVER', t('ACCEPTED_BY_DRIVER', 'Accepted by driver'), 0.45),
  entry(9, 'PICK_UP_COMPLETED_BY_DRIVER', t('PICK_UP_COMPLETED_BY_DRIVER', 'Pick up completed by driver'), 0.8),
  entry(10, 'PICK_UP_FAILED_BY_DRIVER', t('PICK_UP_FAILED_BY_DRIVER', 'Pick up Failed by driver'), 0),
  entry(11, 'DELIVERY_COMPLETED_BY_DRIVER', t('DELIVERY_COMPLETED_BY_DRIVER', 'Delivery completed by driver'), 1),
  entry(12, 'DELIVERY_FAILED_BY_DRIVER', t('DELIVERY_FAILED_BY_DRIVER', 'Delivery Failed by driver'), 0),
  entry(13, 'PREORDER', t('PREORDER', 'PreOrder'), 0),
  entry(14, 'ORDER_NOT_READY', t('ORDER_NOT_READY', 'Order not ready'), 0),
  entry(15, 'ORDER_PICKEDUP_COMPLETED_BY_CUSTOMER', t('ORDER_PICKEDUP_COMPLETED_BY_CUSTOMER', 'Order picked up completed by customer'), 1),
  entry(16, 'CANCELLED_BY_CUSTOMER', t('CANCELLED_BY_CUSTOMER', 'Cancelled by customer'), 0),
  entry(17, 'ORDER_NOT_PICKEDUP_BY_CUSTOMER', t('ORDER_NOT_PICKEDUP_BY_CUSTOMER', 'Order not picked up by customer'), 0),
  entry(18, 'DRIVER_ALMOST_ARRIVED_TO_BUSINESS', t('DRIVER_ALMOST_ARRIVED_TO_BUSINESS', 'Driver almost arrived to business'), 0.15),
  entry(19, 'DRIVER_ALMOST_ARRIVED_TO_CUSTOMER', t('DRIVER_ALMOST_ARRIVED_TO_CUSTOMER', 'Driver almost arrived to customer'), 0.9),
  entry(20, 'ORDER_CUSTOMER_ALMOST_ARRIVED_BUSINESS', t('ORDER_CUSTOMER_ALMOST_ARRIVED_BUSINESS', 'Customer almost arrived to business'), 0.9),
  entry(21, 'ORDER_CUSTOMER_ARRIVED_BUSINESS', t('ORDER_CUSTOMER_ARRIVED_BUSINESS', 'Customer arrived to business'), 0.95),
  entry(22, 'ORDER_LOOKING_FOR_DRIVER', t('ORDER_LOOKING_FOR_DRIVER', 'Looking for driver'), 0.35),
  entry(23, 'ORDER_DRIVER_ON_WAY', t('ORDER_DRIVER_ON_WAY', 'Driver on way'), 0.45),
  entry(24, 'ORDER_DRIVER_WAITING_FOR_ORDER', t('ORDER_DRIVER_WAITING_FOR_ORDER', 'Driver waiting for order'), 0.25),
  entry(25, 'ORDER_ACCEPTED_BY_DRIVER_COMPANY', t('ORDER_ACCEPTED_BY_DRIVER_COMPANY', 'Accepted by driver company'), 0.25),
  entry(26, 'ORDER_DRIVER_ARRIVED_CUSTOMER', t('ORDER_DRIVER_ARRIVED_CUSTOMER', 'Driver arrived to customer'), 0.8),
]

/** A status of the list (its number as the API sends it, a number or a string), or undefined for one the app does not know. */
export const orderStatusEntry = (t: Translate, status: number | string | null | undefined): OrderStatusEntry | undefined => {
  const key = parseInt(String(status), 10)
  return orderStatusList(t).find((item) => item.key === key)
}

/** The translated name of a status, or undefined for one the app does not know. */
export const orderStatusName = (t: Translate, status: number | string | null | undefined): string | undefined =>
  orderStatusEntry(t, status)?.value
